import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';   // ← ADD THIS
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Dashboard from './pages/Dashboard';
import ProductForm from './pages/ProductForm';
import Sell from './pages/Sell';
import ProductDetails from './pages/ProductDetails';

function App() {
  const [isAuthenticated, setIsAuthenticated] = React.useState(false);

  React.useEffect(() => {
    const storedAuth = localStorage.getItem('campusmart_auth') === 'true';
    setIsAuthenticated(storedAuth);
  }, []);

  const handleAuth = (value) => {
    setIsAuthenticated(value);
    localStorage.setItem('campusmart_auth', value ? 'true' : 'false');
  };

  return (
    <Router>
      <Navbar isAuthenticated={isAuthenticated} onSignOut={() => handleAuth(false)} />
      <div className="app-container">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/post-item" element={<ProductForm />} />
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/login" element={<Login setAuth={handleAuth} />} />
          <Route path="/register" element={<Register setAuth={handleAuth} />} />
          <Route path="/sell" element={<Sell />} />
          <Route path="/add-product" element={<ProductForm />} />
          <Route path="/product/:id" element={<ProductDetails />} />
        </Routes>
      </div>
      // Footer.js mein yeh use karo:
<footer className="site-footer">
  <div className="footer-inner">
    <div className="footer-brand">
      <h3>CampusMart</h3>
      <p>The trusted marketplace for college students to buy and sell items.</p>
    </div>
    <div className="footer-col">
      <h4>Marketplace</h4>
      <Link to="/">Browse Products</Link>
      <Link to="/sell">Sell an Item</Link>
      <Link to="/dashboard">My Dashboard</Link>
    </div>
    <div className="footer-col">
      <h4>Categories</h4>
      <Link to="/">Books</Link>
      <Link to="/">Gadgets</Link>
      <Link to="/">Notes</Link>
    </div>
    <div className="footer-col">
      <h4>Support</h4>
      <Link to="/">Help Center</Link>
      <Link to="/">Safety Tips</Link>
      <Link to="/">Contact Us</Link>
    </div>
  </div>
  <div className="footer-bottom">
    © 2026 CampusMart. All rights reserved.
  </div>
</footer>
      <Footer />   {/* ← ADD THIS */}
    </Router>
  );
}

export default App;
